import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as d}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Hello-Agents 学习指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/patterns/agent/hello-agents.md","filePath":"zh/tech/patterns/agent/hello-agents.md","lastUpdated":1780925049000}'),o={name:"zh/tech/patterns/agent/hello-agents.md"};function n(h,t,l,s,i,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="hello-agents-学习指南" tabindex="-1">Hello-Agents 学习指南 <a class="header-anchor" href="#hello-agents-学习指南" aria-label="Permalink to &quot;Hello-Agents 学习指南&quot;">​</a></h1><blockquote><p>原文：<a href="https://datawhalechina.github.io/hello-agents/" target="_blank" rel="noreferrer">Hello-Agents - 从零开始构建智能体</a> — Datawhale</p></blockquote><h2 id="项目概述" tabindex="-1">项目概述 <a class="header-anchor" href="#项目概述" aria-label="Permalink to &quot;项目概述&quot;">​</a></h2><p>如果说 2024 年是&quot;百模大战&quot;元年，2025 年则开启了 <strong>Agent 元年</strong>。Hello-Agents 是 Datawhale 社区的系统性智能体学习教程，旨在提供从零开始、理论与实战并重的智能体构建指南。</p><h2 id="两类-agent-构建路径" tabindex="-1">两类 Agent 构建路径 <a class="header-anchor" href="#两类-agent-构建路径" aria-label="Permalink to &quot;两类 Agent 构建路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>代表</th><th>本质</th></tr></thead><tbody><tr><td><strong>流程驱动类</strong></td><td>Dify、Coze、n8n</td><td>软件工程，LLM 作为后端数据处理</td></tr><tr><td><strong>AI 原生类</strong></td><td>AutoGen、LangGraph、helloagents</td><td>真正以 AI 驱动的 Agent（本教程重点）</td></tr></tbody></table><h2 id="教程内容导航" tabindex="-1">教程内容导航 <a class="header-anchor" href="#教程内容导航" aria-label="Permalink to &quot;教程内容导航&quot;">​</a></h2><h3 id="第一部分-智能体基础" tabindex="-1">第一部分：智能体基础 <a class="header-anchor" href="#第一部分-智能体基础" aria-label="Permalink to &quot;第一部分：智能体基础&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>关键内容</th></tr></thead><tbody><tr><td>初识智能体</td><td>Agent 定义、类型、范式与应用</td></tr><tr><td>智能体发展史</td><td>从符号主义到 LLM 驱动的演进</td></tr><tr><td>大语言模型基础</td><td>Transformer、提示工程、主流 LLM 及其局限</td></tr></tbody></table><h3 id="第二部分-构建-llm-智能体" tabindex="-1">第二部分：构建 LLM 智能体 <a class="header-anchor" href="#第二部分-构建-llm-智能体" aria-label="Permalink to &quot;第二部分：构建 LLM 智能体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>关键内容</th></tr></thead><tbody><tr><td>智能体经典范式构建</td><td>ReAct、Plan-and-Solve、Reflection 手把手实现</td></tr><tr><td>基于低代码平台的搭建</td><td>Coze、Dify、n8n 等平台使用</td></tr><tr><td>框架开发实践</td><td>AutoGen、AgentScope、LangGraph 等主流框架</td></tr><tr><td>构建你的 Agent 框架</td><td>从 0 开始构建自己的智能体框架</td></tr></tbody></table><h3 id="第三部分-高级知识扩展" tabindex="-1">第三部分：高级知识扩展 <a class="header-anchor" href="#第三部分-高级知识扩展" aria-label="Permalink to &quot;第三部分：高级知识扩展&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>关键内容</th></tr></thead><tbody><tr><td>记忆与检索</td><td>记忆系统、RAG、存储</td></tr><tr><td>上下文工程</td><td>持续交互的&quot;情境理解&quot;</td></tr><tr><td>智能体通信协议</td><td>MCP、A2A、ANP 等协议解析</td></tr><tr><td>Agentic-RL</td><td>从 SFT 到 GRPO 的 LLM 训练实战</td></tr><tr><td>智能体性能评估</td><td>核心指标、基准测试与评估框架</td></tr></tbody></table><h3 id="第四部分-综合案例" tabindex="-1">第四部分：综合案例 <a class="header-anchor" href="#第四部分-综合案例" aria-label="Permalink to &quot;第四部分：综合案例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>案例</th><th>说明</th></tr></thead><tbody><tr><td>智能旅行助手</td><td>MCP 与多智能体协作的真实世界应用</td></tr><tr><td>自动化深度研究 Agent</td><td>DeepResearch Agent 复现与解析</td></tr><tr><td>赛博小镇</td><td>Agent 与游戏结合，模拟社会动态</td></tr></tbody></table><h2 id="核心范式速查" tabindex="-1">核心范式速查 <a class="header-anchor" href="#核心范式速查" aria-label="Permalink to &quot;核心范式速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>范式</th><th>说明</th></tr></thead><tbody><tr><td><strong>ReAct</strong></td><td>Reason + Act，推理-行动循环</td></tr><tr><td><strong>Plan-and-Solve</strong></td><td>先规划再执行</td></tr><tr><td><strong>Reflection</strong></td><td>自我反思改进</td></tr><tr><td><strong>Tool Use</strong></td><td>函数调用/工具调用</td></tr><tr><td><strong>Memory</strong></td><td>短/长期记忆管理</td></tr><tr><td><strong>Multi-Agent</strong></td><td>多智能体协作</td></tr></tbody></table><h2 id="协议对比" tabindex="-1">协议对比 <a class="header-anchor" href="#协议对比" aria-label="Permalink to &quot;协议对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>协议</th><th>说明</th></tr></thead><tbody><tr><td><strong>MCP</strong></td><td>Model Context Protocol，模型上下文协议</td></tr><tr><td><strong>A2A</strong></td><td>Agent to Agent，智能体间通信协议</td></tr><tr><td><strong>ANP</strong></td><td>Agent Network Protocol</td></tr></tbody></table><h2 id="资源链接" tabindex="-1">资源链接 <a class="header-anchor" href="#资源链接" aria-label="Permalink to &quot;资源链接&quot;">​</a></h2><ul><li>在线阅读：<a href="https://datawhalechina.github.io/hello-agents/" target="_blank" rel="noreferrer">datawhalechina.github.io/hello-agents</a></li><li>GitHub：<a href="https://github.com/datawhalechina/hello-agents" target="_blank" rel="noreferrer">datawhalechina/Hello-Agents</a></li><li>自研框架：<a href="https://github.com/jjyaoao/helloagents" target="_blank" rel="noreferrer">jjyaoao/helloagents</a></li></ul>',21)])])}const m=e(o,[["render",n]]);export{f as __pageData,m as default};
